    auto preview_source=state_;if(friendly_->quoted_watcom_seed)preview_source.watcom_seed=*friendly_->quoted_watcom_seed;const auto preview=quote_friendly_booking(preview_source,friendly_->actor,opponent,true,friendly_->sequence,resources_.reference);friendly_->selected=opponent;friendly_->offer.reset();ui::FriendlyMatchState result;result.revision=owner_.revision;result.manager_slot=native_actor(preview.projection,friendly_->actor);result.runtime_team=int(preview.projection.local_club(friendly_->own));result.current_day=state_.calendar->next_day;result.planner_count=int(state_.friendly_plan->pending.size()*2);result.season_start_counter=state_.date-state_.calendar->next_day;result.mode_three=options_.mode==3;result.national_team=friendly_->national;result.owned_world12=true;result.accepted_background=frame;result.selected_opponent=int(preview.projection.local_club(opponent));result.calendar=ui::world12_calendar_state(state_,resources_.german,*resources_.texts);const auto person=std::find_if(state_.world.managers.begin(),state_.world.managers.end(),[&](const auto& m){return m.seat==friendly_->actor;});result.manager_name=person->name;result.first_request_id=friendly_->sequence;result.venue_question=question(state_,preview.projection,result.manager_slot,0x606,message_text(preview.projection.state,layout::Controller_ClubFriendlyState_TextPointer));return result;
