void Session::close_friendly(){if(preparation_menu_!=6||!friendly_)throw FormatError("world12: no friendly menu owner to close");if(friendly_->quoted_watcom_seed){if((friendly_->offer&&state_!=friendly_->offer->source_binding)||owner_.revision==UINT64_MAX)throw FormatError("world12: friendly quote cancellation owner changed");state_.watcom_seed=*friendly_->quoted_watcom_seed;++owner_.revision;}friendly_.reset();preparation_menu_.reset();}
